import{_ as e,o as a,c as t,a2 as s}from"./chunks/framework.CnJ-JtFX.js";const g=JSON.parse('{"title":"EP.18 拖拽落点之谜","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.18-mini-lowcode-designer.md","filePath":"comics/EP.18-mini-lowcode-designer.md","lastUpdated":1792683644000}'),r={name:"comics/EP.18-mini-lowcode-designer.md"};function l(n,i,d,o,h,p){return a(),t("div",null,[...i[0]||(i[0]=[s('<h1 id="ep-18-拖拽落点之谜" tabindex="-1">EP.18 拖拽落点之谜 <a class="header-anchor" href="#ep-18-拖拽落点之谜" aria-label="Permalink to &quot;EP.18 拖拽落点之谜&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/18-mini-lowcode-designer">guide/18-mini-lowcode-designer</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>拖拽困惑</strong>：标签君拖了一个按钮到画布，面对三个已有组件，不知道新按钮该放哪。</li><li><strong>三种落点</strong>：像素酱画出拖拽的三种落点——before（插到目标前面）、after（插到目标后面）、inside（作为子节点插入）。</li><li><strong>禁止操作</strong>：演示两种禁止的拖法——不能把节点拖进自己的子孙（会形成循环引用）、不能往非容器节点里 inside（按钮没有 children）。</li><li><strong>纯函数</strong>：码叔总结——落点判断要做成纯函数，输入 Schema + 拖拽节点 + 目标 + 位置，输出落点结果，才好写单测、好调试。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-拖拽不是随便放" tabindex="-1">第一格：拖拽不是随便放 <a class="header-anchor" href="#第一格-拖拽不是随便放" aria-label="Permalink to &quot;第一格：拖拽不是随便放&quot;">​</a></h3><p>可视化设计器的核心交互是拖拽。用户从组件面板拖一个组件到画布，落到某个位置。这个「位置」不是随便的，必须精确判断是 before、after 还是 inside，否则 Schema 会乱。</p><p>拖拽交互的复杂度在于：画布上有很多节点，鼠标移动时要实时计算落点，还要处理各种禁止情况。</p><h3 id="第二格-三种落点" tabindex="-1">第二格：三种落点 <a class="header-anchor" href="#第二格-三种落点" aria-label="Permalink to &quot;第二格：三种落点&quot;">​</a></h3><p>拖拽落点只有三种，对应 Schema 的三种修改方式：</p><table tabindex="0"><thead><tr><th>落点</th><th>含义</th><th>Schema 操作</th></tr></thead><tbody><tr><td>before</td><td>插到目标节点前面</td><td>在目标节点的兄弟数组中，目标位置前插入</td></tr><tr><td>after</td><td>插到目标节点后面</td><td>在目标节点的兄弟数组中，目标位置后插入</td></tr><tr><td>inside</td><td>作为目标节点的子节点</td><td>追加到目标节点的 children 数组</td></tr></tbody></table><p>判断哪种落点的依据是鼠标在目标节点上的位置：上半部分是 before，下半部分是 after，中间区域是 inside（仅容器）。</p><h3 id="第三格-两种禁止操作" tabindex="-1">第三格：两种禁止操作 <a class="header-anchor" href="#第三格-两种禁止操作" aria-label="Permalink to &quot;第三格：两种禁止操作&quot;">​</a></h3><p>不是所有拖法都合法，有两种必须禁止：</p><ol><li><strong>不能拖进自己的子孙</strong>：如果 A 是 B 的祖先，A 不能拖到 B 里面（before / after / inside 都不行），否则会形成循环引用（A 的 children 包含 B，B 的 children 又包含 A），递归渲染时栈溢出。</li><li><strong>非容器不能 inside</strong>：只有容器类型的节点（page、container）才有 children 字段。按钮、文本等叶子节点没有 children，不能往它们里面 inside。</li></ol><h3 id="第四格-纯函数才好测试" tabindex="-1">第四格：纯函数才好测试 <a class="header-anchor" href="#第四格-纯函数才好测试" aria-label="Permalink to &quot;第四格：纯函数才好测试&quot;">​</a></h3><p>落点判断逻辑应该封装成<strong>纯函数</strong>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getDropPosition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">draggedId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">targetId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">pointerPos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DropResult</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li>输入：Schema 树、拖拽节点 id、目标节点 id、鼠标在目标上的相对位置；</li><li>输出：落点结果（position + parentId + index）或 null（禁止）。</li></ul><p>纯函数的好处：</p><ul><li>没有副作用，相同输入永远产生相同输出；</li><li>好写单测——构造各种 Schema 和拖拽场景，断言输出；</li><li>好调试——出问题时只需检查输入输出，不用考虑状态。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>before / after / inside 判断不准</strong>：鼠标位置和落点的映射要精确，上 1/4 是 before，下 1/4 是 after，中间是 inside，否则用户体验差。</li><li><strong>忘记检查子孙关系</strong>：拖进自己子孙会导致循环引用，递归渲染栈溢出。必须用 <code>isDescendant(dragged, target)</code> 检查。</li><li><strong>非容器 inside 没拦截</strong>：按钮、文本等叶子节点没有 children，往里面 inside 会导致 children 字段被强行添加，数据不一致。</li><li><strong>落点判断和 DOM 耦合</strong>：不要直接读 DOM 的位置来判断落点，应该用 Schema 的节点位置 + 鼠标坐标计算，否则虚拟列表等场景会出错。</li><li><strong>拖拽时的视觉反馈</strong>：before / after / inside 要有不同的视觉提示（如蓝色线、蓝色框），否则用户不知道会落到哪。</li><li><strong>拖到画布空白处</strong>：用户拖到没有节点的空白区域，应该默认 inside 到根容器（page），而不是什么都不做。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 拖拽落点有哪三种？分别对应 Schema 的什么操作？</b></summary><p>三种落点：</p><ol><li><strong>before</strong>：插到目标节点前面。Schema 操作是在目标节点的父节点的 children 数组中，在目标节点的位置前插入新节点。</li><li><strong>after</strong>：插到目标节点后面。Schema 操作是在目标节点的父节点的 children 数组中，在目标节点的位置后插入新节点。</li><li><strong>inside</strong>：作为目标节点的子节点。Schema 操作是把新节点追加（或插入到指定 index）到目标节点的 children 数组。</li></ol><p>判断依据是鼠标在目标节点上的相对位置：上半部分 before，下半部分 after，中间区域 inside（仅容器节点支持 inside）。</p></details><details><summary><b>2. 为什么不能把一个节点拖进自己的子孙节点里？</b></summary><p>因为会形成<strong>循环引用</strong>。</p><p>假设 A 是 B 的祖先（A 的 children 链里包含 B），如果把 A 拖进 B 里面，那么 B 的 children 里就包含 A，而 A 的 children 里又包含 B，形成 A → B → A → B ... 的无限循环。</p><p>后果：</p><ul><li>Renderer 递归渲染时会无限递归，最终栈溢出；</li><li>History 记录变更时也会出问题；</li><li>Schema 序列化时可能栈溢出或数据丢失。</li></ul><p>所以 Designer 在落点判断时必须检查 <code>isDescendant(draggedId, targetId)</code>，如果拖拽节点是目标节点的祖先，就返回 null 禁止放置。</p></details><details><summary><b>3. 为什么落点判断要做成纯函数？</b></summary><p>因为纯函数有三个优势：</p><ol><li><strong>好测试</strong>：纯函数没有副作用，相同输入永远产生相同输出。可以构造各种 Schema 和拖拽场景（正常 before、拖进子孙、非容器 inside 等），写断言验证输出，覆盖所有边界情况。</li><li><strong>好调试</strong>：出问题时只需打印输入参数和返回值，不用考虑组件状态、DOM 状态等外部因素，定位问题更快。</li><li><strong>可复用</strong>：纯函数不依赖 UI 框架，可以在 Designer 的不同部分（拖拽、键盘移动、右键菜单）复用，也可以在单测里直接调用。</li></ol><p>如果落点判断和 DOM 耦合（直接读 DOM 位置），就会变成有副作用的函数，测试要模拟 DOM，调试要看浏览器状态，维护成本高。</p></details>',27)])])}const k=e(r,[["render",l]]);export{g as __pageData,k as default};
